public class GUPVendPriceAdmCopy extends RunBase
{
    #DEFINE.CurrentVersion(1)
    #LOCALMACRO.CurrentList
        chgItemCode,
        chgACCode,
        chgACRelation,
        newItemCode,
        newACCode,
        newACRelation
    #ENDMACRO

    DialogRunbase           dialog;
    
    QueryRun                queryRun;
    Counter                 progressCounter;
    Counter                 progressTotal;

    DialogField             fieldChgItemCode;
    DialogField             fieldChgACCode;
    DialogField             fieldChgACRelation;
    
    DialogField             fieldNewItemCode;
    DialogField             fieldNewACCode;
    DialogField             fieldNewACRelation;
    
    NoYes                   chgItemCode;
    NoYes                   chgACCode;
    NoYes                   chgACRelation;
    
    ItemIdSmall             newItemCode;
    GUPVendPriceAccountCode newACCode;
    GUPVendPriceRelation    newACRelation;
    CustVendRel             prevACRel;
    
}

