    private DialogField addToggleField(FieldLabel _label, FieldHelp _help)
    {
        DialogField result = dialog.addField(enumStr(NoYes), _label, _help);

        result.registerOverrideMethod(methodStr(FormCheckBoxControl, modified), methodStr(GUPVendPriceAdmCopy, enableControls), this);
        
        return result;
    }

    public Object dialog()
    {
        DialogGroup             dialogGroup;
        DialogGroup             chgGroup;
        DialogGroup             newGroup;
        FormBuildStringControl  newControl;

        dialog = super();
        
        dialogGroup = dialog.addGroup();
        chgGroup    = dialog.addGroup("@SYS138761", dialogGroup);

        fieldChgItemCode   = this.addToggleField("@SYS58740", "@SYS138766");
        fieldChgACCode     = this.addToggleField("@SYS12243", "@SYS138768");
        fieldChgACRelation = this.addToggleField("@SYS265"  , "@SYS138769");
        
        newGroup = dialog.addGroup("@SYS81533", dialogGroup);

        fieldNewItemCode   = dialog.addField(extendedTypeStr(ItemIdSmall), ' ', "@SYS138766");
        fieldNewACCode     = dialog.addField(enumStr(GUPVendPriceAccountCode), ' ', "@SYS138768");
        fieldNewACRelation = dialog.addField(extendedTypeStr(GUPVendPriceRelation), "@SYS2355");

        newControl = fieldNewACRelation.control();
        newControl.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(GUPVendPriceAdmCopy, fieldNewACRelation_lookup), this);
        newControl.registerOverrideMethod(methodStr(FormStringControl, resolveAmbiguousReference), methodStr(GUPVendPriceAdmCopy, fieldNewACRelation_resolveAmbiguousReference), this);

        dialogGroup.columns(2);
        dialogGroup.frameType(1);

        dialog.addMenuItemButton(MenuItemType::Display, menuitemDisplayStr(RunBaseQueryDialog), DialogMenuItemGroup::BottomGrp);

        dialog.allowUpdateOnSelectCtrl(true);
        
        this.enableControls(null);

        return dialog;
    }

private boolean enableControls(FormCheckBoxControl _checkBoxControl)
{
    fieldNewItemCode.enabled(fieldChgItemCode.value());
    fieldNewACCode.enabled(fieldChgACCode.value());
    fieldNewACRelation.enabled(fieldChgACRelation.value());
    
    return true;
}

protected void displayProgress()
{
    this.progressUpdate(strFmt("@SYS60086", tableId2pname(tableNum(GUPVendPriceAdmTrans))));
}

protected void fieldNewACRelation_lookup(FormStringControl _callingControl)
{
    switch (fieldNewACCode.value())
    {
        case TableGroupAll::Table:
            VendTable::lookupVendor(_callingControl);
            break;
        case TableGroupAll::GroupId:
            GUPVendPriceGroup::vendPriceGroupIdLookup(_callingControl);
            break;
    }
}

    protected str fieldNewACRelation_resolveAmbiguousReference(FormStringControl _callingControl)
    {
        GUPVendPriceAdmTrans localGUPVendPriceAdmTrans;
        
        if (fieldNewACCode.value() == TableGroupAll::Table)
        {
            return VendTable::resolveAmbiguousReferenceVendor(_callingControl);
        }

        return _callingControl.text();
    }

public boolean getFromDialog()
{
    chgItemCode   = fieldChgItemCode.value();
    chgACCode     = fieldChgACCode.value();
    chgACRelation = fieldChgACRelation.value();
    
    newItemCode   = fieldNewItemCode.value();
    newACCode     = fieldNewACCode.value();
    newACRelation = fieldNewACRelation.value();
    
    return true;
}

protected void new()
{
    super();
    
    queryRun = new QueryRun(queryStr(GUPVendPriceAdmTrans));
}

public container  pack()
{
    return [#CurrentVersion, #CurrentList, queryRun.pack()];
}

protected void progressUpdate(str _text)
{
    progressCounter++;
    progress.setCount(progressCounter);
    progress.setText(_text);
}

public QueryRun queryRun()
{
    return queryRun;
}

    public void run()
    {
        GUPVendPriceAdmTrans   gupVendPriceAdmTrans;
        RecordSortedList       gupVendPriceAdmTransList = new RecordSortedList(tableNum(GUPVendPriceAdmTrans));

        #macrolib.AviFiles

        gupVendPriceAdmTransList.sortOrder(fieldNum(GUPVendPriceAdmTrans, RecId));

        progressTotal = QueryRun::getQueryRowCount(queryRun.query(), intMax()) * 2;
        
        this.progressInit("@SYS59049", progressTotal, #AviFileCopy);
        
        progress = this.parmProgress();

        ttsbegin;

        while (queryRun.next())
        {
            this.displayProgress();
            
            gupVendPriceAdmTrans = queryRun.get(tableNum(GUPVendPriceAdmTrans));

            gupVendPriceAdmTransList.ins(gupVendPriceAdmTrans);
        }

        if (gupVendPriceAdmTransList.first(gupVendPriceAdmTrans))
        {
            do
            {
                this.displayProgress();
                this.updateNow(gupVendPriceAdmTrans);
            } 
            while (gupVendPriceAdmTransList.next(gupVendPriceAdmTrans));
        }

        ttscommit;
    }

    public boolean  unpack(container _packedClass)
    {
        Integer     version     = RunBase::getVersion(_packedClass);
        container   packedQueryRun;

        switch (version)
        {
            case #CurrentVersion :
                [version, #CurrentList, packedQueryRun] = _packedClass;

                if (SysQuery::isPackedOk(packedQueryRun))
                {
                    queryRun   = new QueryRun(packedQueryRun);
                }
                else
                {
                    return false;
                }
                break;
            default :
                return false;
        }

        return true;
    }

    protected void updateNow(GUPVendPriceAdmTrans _gupVendPriceAdmTrans)
    {
        GUPVendPriceAdmTrans newGUPVendPriceAdmTrans = this.initializeGUPVendPriceAdmTransCopy(_gupVendPriceAdmTrans);

        if (! newGUPVendPriceAdmTrans.validateWrite())
        {
            throw error("@SYS326740");
        }
        
        newGUPVendPriceAdmTrans.insert();
    }

    protected GUPVendPriceAdmTrans initializeGUPVendPriceAdmTransCopy(GUPVendPriceAdmTrans _gupVendPriceAdmTrans)
    {
        GUPVendPriceAdmTrans newGUPVendPriceAdmTrans = _gupVendPriceAdmTrans.data();

        if (chgItemCode)
        {
            newGUPVendPriceAdmTrans.ItemNum = newItemCode;
        }

        if (chgACCode)
        {
            newGUPVendPriceAdmTrans.AccountCode = newACCode;
        }

        if (chgACRelation)
        {
            newGUPVendPriceAdmTrans.AccountRelation = newACRelation;
        }
        
        return newGUPVendPriceAdmTrans;
    }

    private void clearProductDimensions(GUPVendPriceAdmTrans _gupVendPriceAdmTrans)
    {
        InventDim inventDim = _gupVendPriceAdmTrans.inventDim();
        
        if (this.shouldClearProductDimensions(inventDim))
        {
            inventDim.clearProductDimensions();

            _gupVendPriceAdmTrans.InventDimId = inventDim::findOrCreate(inventDim).inventDimId;
        }
    }

private boolean shouldClearProductDimensions(InventDim _inventDim)
{
    return _inventDim.anyProductDimensionSpecified();
}

    public void  updateQueryBuild(GUPVendPriceAdmTrans _gupVendPriceAdmTrans)
    {
        QueryBuildRange queryBuildRange;

        queryBuildRange = queryRun.query().dataSourceTable(tableNum(GUPVendPriceAdmTrans)).findRange(fieldNum(GUPVendPriceAdmTrans, JournalNum));
        queryBuildRange.value(queryValue(_gupVendPriceAdmTrans.JournalNum));
        queryBuildRange.status(RangeStatus::Hidden);
        queryRun.title(GUPVendPriceAdmCopy::description());
    }

public boolean validate(Object _calledFrom = null)
{
    return true;
}

public static GUPVendPriceAdmCopy construct()
{
    return new GUPVendPriceAdmCopy();
}

public static ClassDescription description()
{
    return "@GlobalUnifiedPricing:GUPVendPriceAdm_CopyReviseDesc";
}

    public static void main(Args args)
    {
        GUPVendPriceAdmTrans gupVendPriceAdmTrans;
        GUPVendPriceAdmCopy  gupVendPriceAdmCopy = GUPVendPriceAdmCopy::construct();
        FormDataSource       formDS;

        if (!(args.dataset() == tableNum(GUPVendPriceAdmTrans)))
        {
            throw error("@SYS18626");
        }

        gupVendPriceAdmTrans = args.record();
        
        if (! gupVendPriceAdmTrans.JournalNum)
        {
            throw error("@SYS59048");
        }

        gupVendPriceAdmCopy.getLast();
        gupVendPriceAdmCopy.updateQueryBuild(gupVendPriceAdmTrans);
        
        if (gupVendPriceAdmCopy.prompt())
        {
            gupVendPriceAdmCopy.runOperation();

            if (args.record().isFormDataSource())
            {
                formDS = args.record().dataSource();
                formDS.research(true);
            }
        }
    }

protected boolean canRunInNewSession()
{
    return true;
}
